import { cache, Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

// Deduplicated per request: the three sections share a single fetch.
const getDashboardData = cache(async (): Promise<DashboardData> => {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
})

async function DashboardCards() {
  const { totalRevenue, totalInvoices } = await getDashboardData()
  return <CardStats totalRevenue={totalRevenue} totalInvoices={totalInvoices} />
}

async function DashboardRevenue() {
  const { revenue } = await getDashboardData()
  return <RevenueChart revenue={revenue} />
}

async function DashboardInvoices() {
  const { invoices } = await getDashboardData()
  return <LatestInvoices invoices={invoices} />
}

function CardsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>Loading...</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>Loading...</p>
      </div>
    </div>
  )
}

function SectionSkeleton({ className, title }: { className: string; title: string }) {
  return (
    <div className={className}>
      <h2>{title}</h2>
      <p>Loading...</p>
    </div>
  )
}

// The page itself does no async work, so the heading and every fallback
// are prerendered into the static shell; only the data streams at request time.
export default function Page() {
  // Start the request immediately so all sections await the same in-flight fetch.
  void getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardsSkeleton />}>
        <DashboardCards />
      </Suspense>
      <Suspense fallback={<SectionSkeleton className="chart" title="Revenue" />}>
        <DashboardRevenue />
      </Suspense>
      <Suspense
        fallback={<SectionSkeleton className="invoices" title="Latest Invoices" />}
      >
        <DashboardInvoices />
      </Suspense>
    </main>
  )
}

